import { LogicWrapper, MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers } from 'kea'

import { integrationsLogic } from 'lib/integrations/integrationsLogic'
import { userLogic } from 'scenes/userLogic'

import { IntegrationType, UserType } from '~/types'

export interface SlackConnectLogicProps {
    connectKey: string
    onConnected?: (integrationId: number) => void
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface slackConnectLogicValues {
    slackIntegrations: IntegrationType[] | undefined // integrationsLogic
    user: UserType | null // userLogic
    waitingForSlack: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface slackConnectLogicActions {
    loadIntegrationsSuccess: (
        integrations: IntegrationType[],
        payload?: any
    ) => {
        integrations: IntegrationType[]
        payload?: any
    } // integrationsLogic
    startPolling: () => {
        value: true
    } // integrationsLogic
    stopPolling: () => {
        value: true
    } // integrationsLogic
    connectSlackClicked: () => {
        value: true
    }
    slackConnected: (integrationId: number) => {
        integrationId: number
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface slackConnectLogicMeta {
    key: string
}

export type slackConnectLogicType = MakeLogicType<
    slackConnectLogicValues,
    slackConnectLogicActions,
    SlackConnectLogicProps,
    slackConnectLogicMeta
>

/**
 * Connecting Slack runs OAuth in another tab, so the page keeps what the user was filling in. The new
 * workspace reaches this tab only through the integrations poller, which also refetches on focus.
 */
export const slackConnectLogic: LogicWrapper<slackConnectLogicType> = kea<slackConnectLogicType>([
    props({} as SlackConnectLogicProps),
    key((props) => props.connectKey),
    path((key) => ['lib', 'integrations', 'slackConnectLogic', key]),
    connect(() => ({
        values: [integrationsLogic, ['slackIntegrations'], userLogic, ['user']],
        actions: [integrationsLogic, ['startPolling', 'stopPolling', 'loadIntegrationsSuccess']],
    })),
    actions({
        connectSlackClicked: true,
        slackConnected: (integrationId: number) => ({ integrationId }),
    }),
    reducers({
        waitingForSlack: [
            false,
            {
                connectSlackClicked: () => true,
                slackConnected: () => false,
            },
        ],
    }),
    listeners(({ actions, values, props, cache }) => ({
        connectSlackClicked: () => {
            // Before the first successful load there is nothing to compare against, so the next load sets the baseline.
            cache.knownSlackIntegrationIds = values.slackIntegrations
                ? new Set(values.slackIntegrations.map((integration) => integration.id))
                : null
            // The poller counts subscribers, so the same key keeps a second click from adding one that
            // nothing stops. It keeps running while this tab is hidden, because the user is in the
            // Slack tab then and the focus refetch is what brings the workspace back.
            cache.disposables.add(
                () => {
                    actions.startPolling()
                    return () => actions.stopPolling()
                },
                'integrationsPolling',
                { pauseOnPageHidden: false }
            )
        },
        loadIntegrationsSuccess: ({ integrations }) => {
            if (!values.waitingForSlack) {
                return
            }
            const slackIntegrations = integrations.filter((integration) => integration.kind === 'slack')
            const known: Set<number> | null = cache.knownSlackIntegrationIds
            if (!known) {
                cache.knownSlackIntegrationIds = new Set(slackIntegrations.map((integration) => integration.id))
                return
            }
            // Another member can add a workspace to the project meanwhile; only this user's OAuth counts.
            const workspace = slackIntegrations.find(
                (integration) =>
                    !known.has(integration.id) && !!values.user && integration.created_by?.uuid === values.user.uuid
            )
            if (workspace) {
                actions.slackConnected(workspace.id)
            }
        },
        slackConnected: ({ integrationId }) => {
            cache.disposables.dispose('integrationsPolling')
            props.onConnected?.(integrationId)
        },
    })),
])
